let localeKeys=[],localePattern=/(?!)/g,localeSourceSignature='';
function refreshLocaleDictionary(force=false){
 const sources=[
  typeof featureJapanese!=='undefined'?featureJapanese:null,
  typeof expansionJapanese!=='undefined'?expansionJapanese:null,
  typeof yamanashiJapanese!=='undefined'?yamanashiJapanese:null,
  typeof osakaJapanese!=='undefined'?osakaJapanese:null,
  typeof municipalJapanese!=='undefined'?municipalJapanese:null,
  typeof regionalJapanese!=='undefined'?regionalJapanese:null,
  typeof photoQaJapanese!=='undefined'?photoQaJapanese:null,
  typeof mapQaJapanese!=='undefined'?mapQaJapanese:null
 ];
 const signature=sources.map(o=>o?Object.keys(o).length:0).join(':');
 if(!force&&signature===localeSourceSignature)return;
 for(const key of Object.keys(jaDictionary))delete jaDictionary[key];
 Object.assign(jaDictionary,localeBase);
 for(const src of sources.slice(0,6))if(src)Object.assign(jaDictionary,src);
 Object.assign(jaDictionary,localeSupplemental);
 for(const src of sources.slice(6))if(src)Object.assign(jaDictionary,src);
 localeKeys=Object.keys(jaDictionary).sort((a,b)=>b.length-a.length);
 localePattern=new RegExp(localeKeys.map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
 localeSourceSignature=signature;
}
refreshLocaleDictionary(true);
function translateText(text,force=false){refreshLocaleDictionary();if(language!=='ja'&&!force)return text;return jaDictionary[text]||text.replace(localePattern,s=>jaDictionary[s]);}
function localize(){
 refreshLocaleDictionary();
 const walk=document.createTreeWalker(document.body,4);let node;
 while(node=walk.nextNode()){
  if(node.parentElement?.closest('script,style,.language,[translate="no"],[data-user-content],[data-municipality-id],textarea'))continue;
  const old=localeNodes.get(node);const original=old&&node.nodeValue===old.last?old.original:node.nodeValue;
  const value=translateText(original);if(node.nodeValue!==value)node.nodeValue=value;localeNodes.set(node,{original,last:value});
 }
 for(const el of document.querySelectorAll('[placeholder],[aria-label],[title],[alt]')){
  if(el.closest('.language,[data-municipality-id],[data-municipality-aria]'))continue;let savedAttrs=localeAttrs.get(el)||{};
  for(const attr of ['placeholder','aria-label','title','alt']){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr),old=savedAttrs[attr],original=old&&current===old.last?old.original:current,value=translateText(original);if(current!==value)el.setAttribute(attr,value);savedAttrs[attr]={original,last:value}}
  localeAttrs.set(el,savedAttrs);
 }
 localizeMunicipalLabels();
 document.documentElement.lang=language;document.title=language==='ja'?'Jatlas · 日本':'Jatlas · 일본';
 for(const [id,l]of [['langKo','ko'],['langJa','ja']]){const el=document.getElementById(id);el.classList.toggle('active',language===l);el.setAttribute('aria-pressed',String(language===l))}
}
